RustoBindingErrorException _uniffiLiftRustoBindingErrorException(Uint8List bytes) {
  final RustoBindingError value = _uniffiDecodeRustoBindingError(bytes);
  if (value is RustoBindingErrorInitialization) {
    return RustoBindingErrorExceptionInitialization(
      msg: value.msg,
    );
  }
  if (value is RustoBindingErrorPreprocess) {
    return RustoBindingErrorExceptionPreprocess(
      msg: value.msg,
    );
  }
  if (value is RustoBindingErrorInference) {
    return RustoBindingErrorExceptionInference(
      msg: value.msg,
    );
  }
  if (value is RustoBindingErrorPostprocess) {
    return RustoBindingErrorExceptionPostprocess(
      msg: value.msg,
    );
  }
  if (value is RustoBindingErrorInvalidInput) {
    return RustoBindingErrorExceptionInvalidInput(
      msg: value.msg,
    );
  }
  throw StateError('Unknown RustoBindingError error variant while lifting exception: $value');
}

String _encodeDetectTextResult(DetectTextResult value) {
  if (value is DetectTextResultStructured) {
    return jsonEncode({
      'tag': 'structured',
      'results': value.results.map((item) => item.toJson()).toList(),
    });
  }
  if (value is DetectTextResultSpatial) {
    return jsonEncode({
      'tag': 'spatial',
      'text': value.text,
    });
  }
  throw StateError('Unknown DetectTextResult variant instance: $value');
}

DetectTextResult _decodeDetectTextResult(String raw) {
  final Map<String, dynamic> map = jsonDecode(raw) as Map<String, dynamic>;
  final String? tag = map['tag'] as String?;
  switch (tag) {
    case 'structured':
      return DetectTextResultStructured(
        results: (map['results'] as List).map((item) => TextResult.fromJson(item as Map<String, dynamic>)).toList(),
      );
    case 'spatial':
      return DetectTextResultSpatial(
        text: map['text'] as String,
      );
    default:
      throw StateError('Unknown DetectTextResult variant tag: $tag');
  }
}

String _encodeImageSource(ImageSource value) {
  if (value is ImageSourcePath) {
