RustoBindingError _decodeRustoBindingError(String raw) {
  final Map<String, dynamic> map = jsonDecode(raw) as Map<String, dynamic>;
  final String? tag = map['tag'] as String?;
  switch (tag) {
    case 'initialization':
      return RustoBindingErrorInitialization(
        msg: map['msg'] as String,
      );
    case 'preprocess':
      return RustoBindingErrorPreprocess(
        msg: map['msg'] as String,
